-- MorantxHub public release: Base64-encoded Lua. This is encoding, not encryption.
local encoded=[=[]=]
local abc="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local reverse={}
for i=1,#abc do reverse[abc:sub(i,i)]=i-1 end
local output,acc,n={},0,0
for i=1,#encoded do
    local d=reverse[encoded:sub(i,i)]
    if d then
        acc=acc*64+d; n=n+6
        if n>=8 then
            n=n-8; output[#output+1]=string.char(math.floor(acc/2^n)%256)
            acc=acc%(2^n)
        end
    end
end
local fn,err=loadstring(table.concat(output))
assert(fn, "[MorantxHub] " .. tostring(err))
return fn()
